+const form = document.querySelector("#notification-form");
+const radioGroup = document.querySelector(".radio-group");
+const radios = Array.from(
+  document.querySelectorAll('input[name="notificationPreference"]'),
+);
+const errorMessage = document.querySelector("#notification-error");
+const formStatus = document.querySelector("#form-status");
+
+function selectedPreference() {
+  return radios.find((radio) => radio.checked);
+}
+
+function setGroupInvalid(isInvalid) {
+  radioGroup.classList.toggle("has-error", isInvalid);
+  radios.forEach((radio) => {
+    radio.setAttribute("aria-invalid", String(isInvalid));
+  });
+}
+
+function clearFeedback() {
+  errorMessage.textContent = "";
+  formStatus.textContent = "";
+  setGroupInvalid(false);
+}
+
+radios.forEach((radio) => {
+  radio.addEventListener("change", clearFeedback);
+});
+
+form.addEventListener("submit", (event) => {
+  event.preventDefault();
+
+  const selectedRadio = selectedPreference();
+
+  if (!selectedRadio) {
+    errorMessage.textContent = "Select how you prefer to receive notifications.";
+    formStatus.textContent = "";
+    setGroupInvalid(true);
+    radios[0].focus();
+    return;
+  }
+
+  clearFeedback();
+  formStatus.textContent = `Saved preference: ${selectedRadio.value}.`;
+});
*** End Patch
