  color-scheme: light;
  --color-page: #f4f7fb;
  --color-surface: #ffffff;
  --color-text: #172033;
  --color-muted: #5d6b82;
  --color-border: #c8d1df;
  --color-border-strong: #6b7a90;
  --color-primary: #2352c7;
  --color-primary-strong: #173e99;
  --color-primary-soft: #eef4ff;
  --color-error: #b42318;
  --color-success: #126b35;
  --shadow-card: 0 24px 70px #c8d1df;
  --radius-lg: 28px;
  --radius-md: 18px;
  --radius-sm: 12px;
}

* {
  box-sizing: border-box;
}

html {
  min-width: 320px;
}

body {
  min-height: 100vh;
  margin: 0;
  color: var(--color-text);
  font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont,
    "Segoe UI", sans-serif;
  background:
    radial-gradient(circle at top left, #dce8ff 0, transparent 32rem),
    linear-gradient(135deg, #f8fbff 0%, var(--color-page) 100%);
}

.skip-link {
  position: absolute;
  left: 1rem;
  top: 1rem;
  z-index: 10;
  transform: translateY(-150%);
  border-radius: 999px;
  padding: 0.75rem 1rem;
  color: #ffffff;
  background: var(--color-primary);
  font-weight: 700;
}

.skip-link:focus {
  transform: translateY(0);
  outline: 3px solid #0b1020;
  outline-offset: 3px;
}

.page-shell {
  display: grid;
  min-height: 100vh;
  place-items: center;
  padding: 2rem;
}

.card {
  width: min(100%, 42rem);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  padding: clamp(1.5rem, 5vw, 3rem);
  background: var(--color-surface);
  box-shadow: var(--shadow-card);
}

.eyebrow {
  margin: 0 0 0.75rem;
  color: var(--color-primary-strong);
  font-size: 0.78rem;
  font-weight: 800;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

h1 {
  margin: 0;
  font-size: clamp(2rem, 6vw, 3.5rem);
  line-height: 1;
  letter-spacing: -0.06em;
}

.intro {
  max-width: 34rem;
  margin: 1rem 0 2rem;
  color: var(--color-muted);
  font-size: 1.05rem;
  line-height: 1.6;
}

form {
  display: grid;
  gap: 1.25rem;
}

.form-field {
  min-width: 0;
}

fieldset {
  min-width: 0;
  margin: 0;
  border: 0;
  padding: 0;
}

legend {
  margin-bottom: 0.35rem;
  padding: 0;
  color: var(--color-text);
  font-size: 1.08rem;
  font-weight: 800;
}

.required-indicator {
  color: var(--color-error);
}

.field-help {
  margin: 0 0 1rem;
  color: var(--color-muted);
  line-height: 1.5;
}

.radio-group {
  display: grid;
  gap: 0.85rem;
}

.radio-card {
  display: grid;
  grid-template-columns: auto 1fr;
  gap: 0.9rem;
  align-items: start;
  min-width: 0;
  border: 2px solid var(--color-border);
  border-radius: var(--radius-md);
  padding: 1rem;
  background: #ffffff;
  cursor: pointer;
  transition:
    border-color 160ms ease,
    background-color 160ms ease,
    transform 160ms ease;
}

.radio-card:hover {
  border-color: var(--color-border-strong);
  background: #fbfdff;
}

.radio-card:has(input:checked) {
  border-color: var(--color-primary);
  background: var(--color-primary-soft);
}

.radio-card:has(input:focus-visible) {
  outline: 3px solid var(--color-primary);
  outline-offset: 3px;
}

.radio-card input {
  width: 1.3rem;
  height: 1.3rem;
  margin: 0.12rem 0 0;
  accent-color: var(--color-primary);
}

.radio-content {
  display: grid;
  gap: 0.25rem;
  min-width: 0;
}

.radio-title {
  font-weight: 800;
}

.radio-description {
  color: var(--color-muted);
  font-size: 0.95rem;
  line-height: 1.45;
  overflow-wrap: anywhere;
}

.field-error {
  min-height: 1.4rem;
  margin: 0.15rem 0 0;
  color: var(--color-error);
  font-weight: 700;
}

.radio-group.has-error .radio-card {
  border-color: var(--color-error);
}

button {
  width: fit-content;
  max-width: 100%;
  border: 0;
  border-radius: var(--radius-sm);
  padding: 0.9rem 1.25rem;
  color: #ffffff;
  background: var(--color-primary);
  font: inherit;
  font-weight: 800;
  cursor: pointer;
  box-shadow: 0 12px 30px #c8d1df;
}

button:hover {
  background: var(--color-primary-strong);
}

button:focus-visible {
  outline: 3px solid #0b1020;
  outline-offset: 3px;
}

.form-status {
  min-height: 1.4rem;
  margin: 0;
  color: var(--color-success);
  font-weight: 700;
}

@media (max-width: 420px) {
  .page-shell {
    align-items: start;
    padding: 1rem;
  }

  .card {
    border-radius: 20px;
  }

  button {
    width: 100%;
  }
}

@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    scroll-behavior: auto !important;
    transition-duration: 0.01ms !important;
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
  }
}

@media (forced-colors: active) {
  .card,
  .radio-card,
  button {
    border: 1px solid ButtonBorder;
    box-shadow: none;
  }

  .radio-card:has(input:checked) {
    border-color: Highlight;
  }

  .field-error {
    color: CanvasText;
  }
}
